warehouse_picking_errors::baseline::v2.text:
{
  "claims": [
    {
      "id": "C1",
      "statement": "The site mispick rate has risen every quarter since 2025-Q3, from 2.5 to 3.9 per 1,000 lines in 2026-Q2.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-9a935b13", "quote": "value: 2.5", "locator": "picking_metrics row 1, 2025-Q3 site_mispick_rate"},
        {"evidence_id": "EV-5079b3e9", "quote": "value: 3.0", "locator": "picking_metrics row 3, 2026-Q1 site_mispick_rate"},
        {"evidence_id": "EV-ef4cc69c", "quote": "value: 3.9", "locator": "picking_metrics row 4, 2026-Q2 site_mispick_rate"}
      ],
      "support_level": "strong",
      "rationale": "Dated quarterly series from the analytics owner, consistent with the mispick log summary for the same periods."
    },
    {
      "id": "C2",
      "statement": "In 2026-Q2 the mispick rate in aisles 31 to 44 was 9.5 per 1,000 lines against 1.6 per 1,000 in all other aisles: the site problem is concentrated in one aisle range.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-3ee7004b", "quote": "rate_per_1000_lines: 9.5", "locator": "mispick log row 7, 2026-Q2 all_shifts aisles_31_44"},
        {"evidence_id": "EV-7e02ec81", "quote": "rate_per_1000_lines: 1.6", "locator": "mispick log row 8, 2026-Q2 all_shifts all_other_aisles"}
      ],
      "support_level": "strong",
      "rationale": "Two rows of the same operational record, same period and denominator basis."
    },
    {
      "id": "C3",
      "statement": "The step change in aisles 31 to 44 is coincident with the February 2026 reslot: 2.5 per 1,000 in January, 6.4 in February (reslot executed 2026-02-09), 9.1 in March, and 9.6 by June.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-6d7fc114", "quote": "value: 2.5", "locator": "picking_metrics row 13, 2026-01 aisle_31_44_mispick_rate"},
        {"evidence_id": "EV-b2b6245b", "quote": "note: synthetic - reslot executed 2026-02-09", "locator": "picking_metrics row 14, 2026-02 aisle_31_44_mispick_rate value 6.4"},
        {"evidence_id": "EV-466711a2", "quote": "value: 9.1", "locator": "picking_metrics row 15, 2026-03 aisle_31_44_mispick_rate"},
        {"evidence_id": "EV-c24978ac", "quote": "value: 9.6", "locator": "picking_metrics row 18, 2026-06 aisle_31_44_mispick_rate"}
      ],
      "support_level": "strong",
      "rationale": "Monthly series with the reslot date recorded in the data. The timing association is strong; causation is not established by these rows alone (see C11 and the gaps)."
    },
    {
      "id": "C4",
      "statement": "Over the same months the rate in all other aisles fell from 2.6 to 1.6 per 1,000, with the aisle 1 to 30 label refresh completed 2026-01-30, so the deterioration is not a site-wide drift.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-1db767c0", "quote": "value: 2.6", "locator": "picking_metrics row 19, 2025-11 all_other_aisles"},
        {"evidence_id": "EV-b938852d", "quote": "note: synthetic - label refresh completed in aisles 1 to 30 on 2026-01-30", "locator": "picking_metrics row 21, 2026-01 all_other_aisles value 2.2"},
        {"evidence_id": "EV-2573868f", "quote": "value: 1.6", "locator": "picking_metrics row 26, 2026-06 all_other_aisles"}
      ],
      "support_level": "strong",
      "rationale": "Contemporaneous comparison series. The label refresh was not measured with a control either, so its contribution to the decline is not isolated."
    },
    {
      "id": "C5",
      "statement": "In aisles 31 to 44 the dominant error type in 2026-Q2 was wrong item, similar SKU: 4,335 mispicks, 6.10 per 1,000 lines, 64% of that group's errors.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-c15b62e0", "quote": "rate_per_1000_lines: 6.10", "locator": "mispick log row 10, 2026-Q2 aisles_31_44 wrong_item_similar_sku, count 4335, share 64.0%"}
      ],
      "support_level": "strong",
      "rationale": "Single operational record with stated numerator and denominator."
    },
    {
      "id": "C6",
      "statement": "Outside aisles 31 to 44 the largest error type is wrong quantity (1,095 errors, 40.5% of that group), so 'similar SKU' and 'quantity' are each the leading cause of a different segment.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-a7cded47", "quote": "share_of_group_percent: 40.5", "locator": "mispick log row 15, 2026-Q2 all_other_aisles wrong_quantity, rate 0.65"},
        {"evidence_id": "EV-2de3aad9", "quote": "rate_per_1000_lines: 0.35", "locator": "mispick log row 16, 2026-Q2 all_other_aisles wrong_item_similar_sku, share 22.0%"}
      ],
      "support_level": "strong",
      "rationale": "Same record family, segmented. Site-wide in Q2 similar-SKU is largest at 52% (EV-3552e637); segment matters."
    },
    {
      "id": "C7",
      "statement": "The reslot placed 38 of 41 confusable description pairs face-adjacent, within 1.2 metres, where the median pre-reslot separation of a pair was 34 metres.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-979e7748", "quote": "38 of the 41 pairs are slotted face-adjacent, within 1.2 metres of one another. 3 are not. The median separation between the two members of a pair before the February reslot was 34 metres.", "locator": "Desk review of the slot map"},
        {"evidence_id": "EV-9521f2f8", "quote": "separation_metres_before_reslot: 41", "locator": "sku_confusion_pairs CP-01, after reslot 0.9 m, 612 mispicks"}
      ],
      "support_level": "strong",
      "rationale": "Desk review of the live slot map plus a per-pair record; both owned by industrial-engineering and dated 2026-07-24."
    },
    {
      "id": "C8",
      "statement": "The confusable pairs the reslot left separated carry almost no mispicks (CP-07: 21; the two remaining non-adjacent pairs: 26 combined) whereas the face-adjacent pairs account for thousands.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-3f0bb944", "quote": "note: synthetic - the reslot left this pair at opposite ends of the bay", "locator": "sku_confusion_pairs CP-07, mispick_count 21, separation after 46.0 m"},
        {"evidence_id": "EV-401a4ae6", "quote": "mispick_count: 26", "locator": "sku_confusion_pairs CP-REST-SEPARATE, 2 pairs, separation after 38.0 m median"},
        {"evidence_id": "EV-c5104cea", "quote": "mispick_count: 1445", "locator": "sku_confusion_pairs CP-REST-ADJACENT, 32 pairs, separation after 0.9 m median"}
      ],
      "support_level": "moderate",
      "rationale": "A natural contrast within the same aisle range, but only 3 pairs are on the separated side and they were not randomly chosen; it is observational, not an experiment."
    },
    {
      "id": "C9",
      "statement": "Direct observation puts the mechanism at the face: 24 of 31 observed errors were in aisles 31 to 44 and 19 of those were a reach to the immediately adjacent face; hesitation at a confusable face was 4.1 seconds against 1.3 elsewhere.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-979e7748", "quote": "24 of the 31 observed errors occurred in aisles 31 to 44. 19 of those 24 were a reach to the immediately adjacent pick face rather than the one on the pick list.", "locator": "What was observed at the face"},
        {"evidence_id": "EV-979e7748", "quote": "Median hesitation time at a face belonging to a confusable pair was 4.1 seconds, against 1.3 seconds at other faces.", "locator": "What was observed at the face"}
      ],
      "support_level": "moderate",
      "rationale": "31 errors over 24 of a 168-hour week in one July week, with observer effects acknowledged by the author. Directionally consistent with the log; too small for sub-breakdowns."
    },
    {
      "id": "C10",
      "statement": "The RF terminal truncates item descriptions to 18 characters and the field cannot be widened before the FY28 WMS core upgrade, which is why identical 18-character prefixes are undetectable to the picker on screen.",
      "claim_type": "technical_constraint",
      "citations": [
        {"evidence_id": "EV-b7efb287", "quote": "The RF pick screen displays the item description truncated to 18 characters. The field width is fixed in the Corvus WMS 7.2 client and cannot be widened before the WMS core upgrade, which is scheduled for FY28.", "locator": "RF terminals"},
        {"evidence_id": "EV-9521f2f8", "quote": "rf_display_text: HAVENMILL OAT DRIN", "locator": "sku_confusion_pairs CP-01 display text"}
      ],
      "support_level": "strong",
      "rationale": "Systems owner document plus the pair record showing the truncated string."
    },
    {
      "id": "C11",
      "statement": "Nothing in the evidence establishes what the error rate at these faces would be if the pairs were separated again; the reslot was executed and monitored with no accuracy measurement designed either side of it.",
      "claim_type": "assumption",
      "citations": [
        {"evidence_id": "EV-979e7748", "quote": "Nothing here establishes what the error rate at these faces would be if the pairs were separated again.", "locator": "Limitations"},
        {"evidence_id": "EV-1d7f300b", "quote": "No accuracy impact was expected, and none was measured before or after the move.", "locator": "D-2026-01"}
      ],
      "support_level": "strong",
      "rationale": "Both sources state the absence explicitly. This is the central untested step in the recommended option."
    },
    {
      "id": "C12",
      "statement": "Slot moves are self-service and need no vendor: bulk moves are supported in the Corvus workbench and a physical face relocation averages 11 minutes including relabelling.",
      "claim_type": "technical_constraint",
      "citations": [
        {"evidence_id": "EV-b7efb287", "quote": "Slot reassignment is available to site users through the Corvus slotting workbench. Bulk moves are supported and need no vendor involvement. Physically relocating a pick face takes an average of 11 minutes including relabelling.", "locator": "Slotting"}
      ],
      "support_level": "moderate",
      "rationale": "A stated average per face with no sample or method given, and no account of knock-on moves when a face is displaced."
    },
    {
      "id": "C13",
      "statement": "Item similarity is not an available input to the Corvus 7.2 slotting rules; adding it is a configuration change the vendor says is possible but has not scoped, so without it any separation achieved now can be undone by the next automated reslot.",
      "claim_type": "technical_constraint",
      "citations": [
        {"evidence_id": "EV-b7efb287", "quote": "Item similarity is not available as an input to the slotting rules in Corvus WMS 7.2. Adding it would be a configuration change to the slotting profile. The vendor has confirmed it is possible but has not scoped it.", "locator": "Slotting"},
        {"evidence_id": "EV-1d7f300b", "quote": "Slot assignment was generated by the Corvus slotting workbench from cube utilisation, pallet height and pick velocity. Item similarity is not an input to the slotting rules and was not considered.", "locator": "D-2026-01"}
      ],
      "support_level": "strong",
      "rationale": "Consistent across the systems document and the decision log."
    },
    {
      "id": "C14",
      "statement": "Four of the 41 pairs sit in allergen-segregated stock and cannot be moved until a documented food-safety review is completed, which typically takes two weeks.",
      "claim_type": "governance_constraint",
      "citations": [
        {"evidence_id": "EV-979e7748", "quote": "Four of the 41 pairs sit in allergen-segregated stock, so any move of those particular faces needs a food-safety review first.", "locator": "Desk review of the slot map"},
        {"evidence_id": "EV-6562cfc0", "quote": "Any slot move involving allergen-segregated or temperature-controlled stock requires a documented food-safety review before the move. Reviews are completed by the site quality team and typically take two weeks.", "locator": "Food safety"}
      ],
      "support_level": "strong",
      "rationale": "Governance policy plus the count of affected pairs. CP-01, the highest-volume pair at 612 mispicks, is allergen-segregated (EV-9521f2f8)."
    },
    {
      "id": "C15",
      "statement": "Cost per line picked is the binding FY26 constraint: any change that adds pick-cycle time must be offset or approved by the regional finance partner.",
      "claim_type": "business_constraint",
      "citations": [
        {"evidence_id": "EV-8f5d5027", "quote": "Cost per line picked is the binding constraint for FY26. Any change that adds time to the pick cycle must be offset by a saving elsewhere, or approved by the regional finance partner before it is rolled out.", "locator": "Priorities and constraints"}
      ],
      "support_level": "strong",
      "rationale": "Stated by site leadership as a constraint, not a preference."
    },
    {
      "id": "C16",
      "statement": "Scan-verify exists but is optional for ambient full-case picks and adds about 2.8 seconds per line; that figure is an average over 38 observed picks and is not a validated time standard.",
      "claim_type": "technical_constraint",
      "citations": [
        {"evidence_id": "EV-979e7748", "quote": "The scan-verify step is optional in Corvus WMS 7.2 for ambient full-case picks and is not enforced.", "locator": "What was observed at the face"},
        {"evidence_id": "EV-979e7748", "quote": "Scanning added 2.8 seconds per line on average. The 2.8-second figure is an average over 38 observed scan-verify picks and should not be treated as a validated time standard.", "locator": "What was observed at the face"},
        {"evidence_id": "EV-b7efb287", "quote": "Keying the check digit is optional for ambient full-case picks under the current configuration.", "locator": "RF terminals"}
      ],
      "support_level": "moderate",
      "rationale": "The existence of the optional step is a documented constraint; the 2.8 s figure has n=38 and is disclaimed by its own author."
    },
    {
      "id": "C17",
      "statement": "The recorded mispick rate is a floor, not a total: an error is logged only if the store files a discrepancy claim within 72 hours, and observed error rates at the face were 26.3 per 1,000 picks against 3.9 per 1,000 lines recorded.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-b7efb287", "quote": "A mispick is recorded only when the receiving store files a discrepancy claim within 72 hours of receipt.", "locator": "How a mispick is recorded"},
        {"evidence_id": "EV-979e7748", "quote": "The observed error rate of 26.3 per 1,000 picks is far above the recorded mispick rate of 3.9 per 1,000 lines.", "locator": "Method"},
        {"evidence_id": "EV-979e7748", "quote": "The recorded figure is a floor, not a total.", "locator": "Method"}
      ],
      "support_level": "strong",
      "rationale": "Definition from the systems owner, corroborated by the observation study. The two rates have different denominators and are not comparable as levels."
    },
    {
      "id": "C18",
      "statement": "The pack-station accuracy audit was suspended on 2026-01-05 and has not restarted, so the interception field for 2026-Q2 exists but was never populated; blank is not zero.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-b35f27bd", "quote": "The pack-station accuracy audit was suspended on 2026-01-05 to release two associates for the reslot. It has not restarted. Interception counts for 2026-Q2 are therefore unavailable.", "locator": "Quality assurance"},
        {"evidence_id": "EV-5e7ea944", "quote": "note: synthetic - pack-station audit suspended 2026-01-05; field exists but was never populated", "locator": "picking_metrics row 49, mispicks_intercepted_at_pack_audit"}
      ],
      "support_level": "strong",
      "rationale": "The metric row carries no value at all."
    },
    {
      "id": "C19",
      "statement": "The 2026-Q2 shift gap (day 2.3, twilight 3.7, night 7.3 per 1,000) is explained by exposure to aisles 31 to 44 rather than by crew: within aisles 31 to 44 the rate is 9.5 to 9.6 on every shift and 1.5 to 1.6 elsewhere on every shift, while night shift takes 71% of its lines from aisles 31 to 44 against 9% on day shift.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-73cc4f66", "quote": "value: 7.3", "locator": "picking_metrics row 10, 2026-Q2 shift_mispick_rate night_shift_c"},
        {"evidence_id": "EV-a4beb4a0", "quote": "rate_per_1000_lines: 9.5", "locator": "mispick log row 1, day_shift_a aisles_31_44"},
        {"evidence_id": "EV-369cf5ac", "quote": "rate_per_1000_lines: 9.6", "locator": "mispick log row 5, night_shift_c aisles_31_44"},
        {"evidence_id": "EV-f198fa5a", "quote": "value: 71.0", "locator": "picking_metrics row 38, share_of_lines_in_aisles_31_44 night_shift_c"},
        {"evidence_id": "EV-2d961c97", "quote": "value: 9.0", "locator": "picking_metrics row 36, share_of_lines_in_aisles_31_44 day_shift_a"}
      ],
      "support_level": "strong",
      "rationale": "Within-aisle-range rates are near-identical across shifts, so the aggregate shift gap is a mix effect. This weakens, without disproving, the labour-mix explanation."
    },
    {
      "id": "C20",
      "statement": "The night shift with the worst headline rate also has 61% agency labour and 4 months median tenure, but within the same aisles its error rate matches the day shift's, so labour mix is not shown to be the driver.",
      "claim_type": "stakeholder_opinion",
      "citations": [
        {"evidence_id": "EV-320c5fb9", "quote": "Give me permanent heads instead of agency and this goes away. You cannot run an accurate operation on people who have been here four months.", "locator": "Ilse Brandt, Night Shift Manager"},
        {"evidence_id": "EV-1a4b2e68", "quote": "value: 61", "locator": "picking_metrics row 41, agency_labour_share night_shift_c"},
        {"evidence_id": "EV-14039eca", "quote": "value: 4", "locator": "picking_metrics row 44, median_associate_tenure night_shift_c"}
      ],
      "opposing_citations": [
        {"evidence_id": "EV-a4beb4a0", "quote": "rate_per_1000_lines: 9.5", "locator": "mispick log row 1, day_shift_a aisles_31_44 (12% agency, 41 months tenure)"},
        {"evidence_id": "EV-7b7275e6", "quote": "rate_per_1000_lines: 1.5", "locator": "mispick log row 6, night_shift_c all_other_aisles"}
      ],
      "support_level": "low",
      "rationale": "A manager's inference. No error-rate breakdown by agency versus permanent labour exists to test it."
    },
    {
      "id": "C21",
      "statement": "The 2023 pick-to-light result is an uncontrolled before/after comparison between the annual volume peak and the annual trough, and in 2026-Q2 the pick-to-light aisles ran at 1.7 per 1,000 against 1.6 in the non-pick-to-light, non-reslotted aisles.",
      "claim_type": "stakeholder_opinion",
      "citations": [
        {"evidence_id": "EV-1d7f300b", "quote": "No concurrent control aisles were used and no other comparison period was reported.", "locator": "D-2023-04 outcome"},
        {"evidence_id": "EV-8f27f29a", "quote": "note: synthetic - the pick-to-light aisles", "locator": "picking_metrics row 27, 2026-Q2 aisle_45_52_mispick_rate value 1.7"},
        {"evidence_id": "EV-f398b395", "quote": "note: synthetic - November is the annual peak", "locator": "picking_metrics row 45, 2024-11 monthly_lines_picked"},
        {"evidence_id": "EV-4b4efb76", "quote": "note: synthetic - August is the annual trough", "locator": "picking_metrics row 46, 2025-08 monthly_lines_picked"}
      ],
      "opposing_citations": [
        {"evidence_id": "EV-1d7f300b", "quote": "aisles 45 to 52 recorded 2.1 mispicks per 1,000 lines in August 2025, against 3.4 per 1,000 in November 2024. The write-up describes this as a 38% reduction and states that the installation has paid for itself.", "locator": "D-2023-04 outcome as reported"}
      ],
      "support_level": "low",
      "rationale": "The claim of a 38% reduction rests on a Nov-2024-to-Aug-2025 comparison across peak and trough with agency share falling from 39% to 21% (EV-69832347, EV-ce697b02). The payback assertion is a recollection, not a costed finding."
    },
    {
      "id": "C22",
      "statement": "The vendor claim behind the vision business case is a 62% reduction across 11 deployments with no stated baseline, site type, observation period or independent evaluation, at an indicative $1.4 million for the pack-line module.",
      "claim_type": "stakeholder_opinion",
      "citations": [
        {"evidence_id": "EV-320c5fb9", "quote": "A vendor whitepaper for a camera-based pick verification product claims a 62% reduction in mispicks across 11 deployments. The indicative price for the pack-line module at this site is $1.4 million.", "locator": "Vendor briefing"},
        {"evidence_id": "EV-320c5fb9", "quote": "The whitepaper does not state the baseline mispick rate at any site, the site types involved, the observation period, or whether those sites changed anything else at the same time.", "locator": "Vendor briefing"}
      ],
      "support_level": "low",
      "rationale": "An unqualified vendor figure. Rule 3: no method, sample or baseline, so it is an opinion about a number."
    },
    {
      "id": "C23",
      "statement": "Ops leadership has asked for an automated pick verification business case for the September capital committee, and the director wants it submitted; the aisles it would cover first have not been decided.",
      "claim_type": "stakeholder_opinion",
      "citations": [
        {"evidence_id": "EV-b35f27bd", "quote": "Ops leadership has asked for a business case for automated pick verification to be prepared for the September capital committee.", "locator": "Ask"},
        {"evidence_id": "EV-320c5fb9", "quote": "I want the vision verification business case in front of the capital committee in September. Every large site in the network will have automated verification within two years and we are behind.", "locator": "Marcus Adeyemi"},
        {"evidence_id": "EV-320c5fb9", "quote": "Asked which aisles the vision system would cover first, he said the team should work that out.", "locator": "Marcus Adeyemi"}
      ],
      "support_level": "low",
      "rationale": "An executive preference. Seniority does not convert it into evidence of effect."
    },
    {
      "id": "C24",
      "statement": "A full reversal of the February reslot is blocked in practice: the returns consolidation cage was commissioned in the released floor space on 2026-03-30 and a full reversal would displace it.",
      "claim_type": "business_constraint",
      "citations": [
        {"evidence_id": "EV-1d7f300b", "quote": "The returns consolidation cage was commissioned in the released floor space on 2026-03-30. A full reversal of the reslot would displace it.", "locator": "D-2026-01"},
        {"evidence_id": "EV-320c5fb9", "quote": "Nobody in the room knew whether the cage could go anywhere else, or what moving it would cost.", "locator": "Open question raised and not answered"}
      ],
      "support_level": "strong",
      "rationale": "Decision log states the physical constraint; the cost of relieving it is unknown."
    },
    {
      "id": "C25",
      "statement": "The March 2026 accuracy refresher reached 210 of 340 associates with no measurement designed, and ran in the same month the reslot effect was still building, so its effect is unmeasured rather than small.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-1d7f300b", "quote": "March 2026, to 210 of 340 associates", "locator": "D-2026-04 delivered"},
        {"evidence_id": "EV-1d7f300b", "quote": "No measurement was designed. The training ran in the same month the reslot effect was still building, so the two cannot be separated.", "locator": "D-2026-04"}
      ],
      "support_level": "strong",
      "rationale": "Stated in the decision log by the owner."
    },
    {
      "id": "C26",
      "statement": "The FY26 goals are a site mispick rate of 2.0 per 1,000 and a 25% reduction in store discrepancy claims; the site is currently moving away from both while remaining inside the 4.0 network tolerance.",
      "claim_type": "business_constraint",
      "citations": [
        {"evidence_id": "EV-8f5d5027", "quote": "Reduce the site mispick rate to 2.0 per 1,000 lines picked by the end of FY26.", "locator": "Annual goals"},
        {"evidence_id": "EV-8f5d5027", "quote": "Reduce store discrepancy claims by 25%.", "locator": "Annual goals"},
        {"evidence_id": "EV-b35f27bd", "quote": "The site mispick rate for 2026-Q2 was 3.9 per 1,000 lines picked, against a network tolerance of 4.0 per 1,000. The site remains inside tolerance.", "locator": "Picking accuracy"}
      ],
      "support_level": "strong",
      "rationale": "Goals from the site strategy document, current position from the quarterly review."
    },
    {
      "id": "C27",
      "statement": "That mispicks are the largest single source of store discrepancy claims is asserted in the FY26 objectives with no claims data behind it anywhere in the evidence.",
      "claim_type": "assumption",
      "citations": [
        {"evidence_id": "EV-8f5d5027", "quote": "Mispicks are the largest single source of store discrepancy claims.", "locator": "Current position"}
      ],
      "support_level": "low",
      "rationale": "No claims volume, claims cost or claim-cause breakdown exists in the evidence to test or size this."
    },
    {
      "id": "C28",
      "statement": "Any camera or sensor system able to identify an individual associate requires works-council consultation (8-12 weeks) and, where a vendor processes associate-identifiable data, a data protection assessment (6-8 weeks) before deployment.",
      "claim_type": "governance_constraint",
      "citations": [
        {"evidence_id": "EV-6562cfc0", "quote": "Any camera or sensor system capable of identifying an individual associate requires works-council consultation before installation. Consultation currently takes eight to twelve weeks.", "locator": "Monitoring of associates"},
        {"evidence_id": "EV-6562cfc0", "quote": "Any vendor processing associate-identifiable data requires a completed data protection assessment before deployment. Assessments currently take six to eight weeks.", "locator": "Vendor assessment"}
      ],
      "support_level": "strong",
